create or replace function public.admin_reporting_summary(p_start timestamptz default now()-interval '30 days', p_end timestamptz default now()) returns jsonb language plpgsql security definer set search_path=public as $$ declare v jsonb; begin if not public.is_admin_user() then raise exception 'admin access required'; end if; if p_end<=p_start then raise exception 'invalid date range'; end if; select jsonb_build_object('period_start',p_start,'period_end',p_end,'orders',coalesce((select count(*) from orders where created_at>=p_start and created_at<p_end),0),'gross_sales',coalesce((select sum(total) from orders where created_at>=p_start and created_at<p_end and payment_status in ('paid','completed','success')),0),'paid_orders',coalesce((select count(*) from orders where created_at>=p_start and created_at<p_end and payment_status in ('paid','completed','success')),0),'delivered_orders',coalesce((select count(*) from orders where created_at>=p_start and created_at<p_end and delivery_status='delivered'),0),'cancelled_orders',coalesce((select count(*) from orders where created_at>=p_start and created_at<p_end and status='cancelled'),0),'new_customers',coalesce((select count(*) from profiles where created_at>=p_start and created_at<p_end),0),'new_products',coalesce((select count(*) from products where created_at>=p_start and created_at<p_end),0),'shipments',coalesce((select count(*) from shipments where created_at>=p_start and created_at<p_end),0),'returns',coalesce((select count(*) from return_requests where created_at>=p_start and created_at<p_end),0)) into v; return v; end $$;
create or replace function public.admin_reporting_daily(p_start date default current_date-29,p_end date default current_date) returns table(day date,orders bigint,sales numeric,new_customers bigint,delivered bigint,returns bigint) language plpgsql security definer set search_path=public as $$ begin if not public.is_admin_user() then raise exception 'admin access required'; end if; if p_end<p_start or p_end-p_start>366 then raise exception 'invalid date range'; end if; return query select d::date,(select count(*) from orders o where o.created_at>=d and o.created_at<d+interval '1 day'),coalesce((select sum(o.total) from orders o where o.created_at>=d and o.created_at<d+interval '1 day' and o.payment_status in ('paid','completed','success')),0),(select count(*) from profiles p where p.created_at>=d and p.created_at<d+interval '1 day'),(select count(*) from orders o where o.created_at>=d and o.created_at<d+interval '1 day' and o.delivery_status='delivered'),(select count(*) from return_requests r where r.created_at>=d and r.created_at<d+interval '1 day') from generate_series(p_start::timestamp,p_end::timestamp,interval '1 day') d order by 1; end $$;
create or replace function public.admin_reporting_top_products(p_start timestamptz default now()-interval '30 days',p_end timestamptz default now(),p_limit integer default 10) returns table(product_id uuid,product_name text,orders bigint) language plpgsql security definer set search_path=public as $$ begin if not public.is_admin_user() then raise exception 'admin access required'; end if; return query select p.id,p.name,count(*) from order_items oi join orders o on o.id=oi.order_id join products p on p.id=oi.product_id where o.created_at>=p_start and o.created_at<p_end group by p.id,p.name order by count(*) desc limit greatest(1,least(p_limit,50)); end $$;
revoke all on function public.admin_reporting_summary(timestamptz,timestamptz) from public,anon,authenticated; grant execute on function public.admin_reporting_summary(timestamptz,timestamptz) to authenticated;
revoke all on function public.admin_reporting_daily(date,date) from public,anon,authenticated; grant execute on function public.admin_reporting_daily(date,date) to authenticated;
revoke all on function public.admin_reporting_top_products(timestamptz,timestamptz,integer) from public,anon,authenticated; grant execute on function public.admin_reporting_top_products(timestamptz,timestamptz,integer) to authenticated;